function draw(){
  const q=qs[index%qs.length];
  if(window.GameForge)window.GameForge.equationPoke(qs,index,gameLevel);
  qEl.innerHTML=(q&&q.ai?'<span class="gf-ai-badge" title="Generated by your configured AI provider">\u2726 AI-GENERATED</span>':'')+escapeHtml(q.q);
  oEl.innerHTML='';q.o.forEach((x,i)=>{const b=document.createElement('button');b.className='equation-option';b.textContent=x;b.addEventListener('click',()=>{if(!gameActive)return;clearInterval(window.__gfEqTimer);if(i===q.a){b.classList.add('good');setScore(score+15+(gameLevel==='godhood'?8:0));setStatus('Correct · next equation.');}else{b.classList.add('bad');setStatus('Not quite · keep the model clean.');}setTimeout(()=>{index++;draw();},330);});oEl.appendChild(b);});
  const paceSecs=(window.GameForge&&window.GameForge.equationPace)?window.GameForge.equationPace(gameLevel):0;
  const paceEl=document.getElementById('equationPace');
  clearInterval(window.__gfEqTimer);window.__gfEqTimer=null;
  if(paceEl){
    if(paceSecs>0){let left=paceSecs;paceEl.textContent='\u23F1 '+left+'s · '+gameLevel.toUpperCase();paceEl.className='equation-pace hot';
      window.__gfEqTimer=setInterval(()=>{if(!gameActive){clearInterval(window.__gfEqTimer);window.__gfEqTimer=null;return;}left--;paceEl.textContent='\u23F1 '+left+'s · '+gameLevel.toUpperCase();if(left<=0){clearInterval(window.__gfEqTimer);window.__gfEqTimer=null;setStatus('Time up · '+gameLevel.toUpperCase()+' pace is unforgiving. Next equation.');index++;draw();}},1000);
    }else{paceEl.textContent=gameLevel.toUpperCase()+' · relaxed pace';paceEl.className='equation-pace';}
  }
}
